import{_ as t,o as i,c as s,a4 as r}from"./chunks/framework.BUqnS5H7.js";const p=JSON.parse('{"title":"端到端实战：从 0 到 1 搭一个生产 Agent","description":"","frontmatter":{},"headers":[],"relativePath":"ai/11-端到端实战.md","filePath":"ai/11-端到端实战.md"}'),d={name:"ai/11-端到端实战.md"};function e(l,a,n,c,o,g){return i(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="端到端实战-从-0-到-1-搭一个生产-agent" tabindex="-1" data-src-line="1" data-src-file="ai/11-端到端实战.md">端到端实战：从 0 到 1 搭一个生产 Agent <a class="header-anchor" href="#端到端实战-从-0-到-1-搭一个生产-agent" aria-label="Permalink to &quot;端到端实战：从 0 到 1 搭一个生产 Agent&quot;">​</a></h1><p data-src-line="3" data-src-file="ai/11-端到端实战.md">前面 10 篇讲的都是「零件」和「原则」——现在要做的，是<strong>把它们装成一台能上线的机器</strong>。</p><p data-src-line="5" data-src-file="ai/11-端到端实战.md">这一篇不教你新概念，而是带你走一遍完整闭环：<strong>需求 → 选型 → 实现 → 评估 → 护栏 → 上线。</strong> 为什么要有这一篇？因为「零件都会了」和「能装出能跑的机器」之间，隔着一条真实的鸿沟——<strong>整合的鸿沟</strong>。前面每篇是「怎么用这个零件」，这一篇是「怎么把这些零件装在一起，还不出错」。</p><hr><h2 id="_1-把零件装成机器-整合的难点在哪" tabindex="-1" data-src-line="9" data-src-file="ai/11-端到端实战.md">1. 把零件装成机器：整合的难点在哪 <a class="header-anchor" href="#_1-把零件装成机器-整合的难点在哪" aria-label="Permalink to &quot;1. 把零件装成机器：整合的难点在哪&quot;">​</a></h2><p data-src-line="11" data-src-file="ai/11-端到端实战.md">先说清楚，为什么「整合」是一道独立的坎。前面 10 篇各自独立时，每个零件都「看起来懂了」；但一旦要装成一台机器，会同时暴露三个新问题：</p><ol data-src-line="13" data-src-file="ai/11-端到端实战.md"><li data-src-line="13" data-src-file="ai/11-端到端实战.md"><strong>零件之间的衔接</strong>：RAG 检索到的内容，怎么传给 Function Calling 的工具？Trace 怎么覆盖「检索 + 调用 + 生成」全链路？这些边界，单篇里都不会讲。</li><li data-src-line="14" data-src-file="ai/11-端到端实战.md"><strong>「够用」的克制</strong>：每个零件都有「加不加」的选择，而整合时最难的，恰恰是<strong>判断「这个场景不需要加」</strong>——用多了是过度设计，用少了是隐患。</li><li data-src-line="15" data-src-file="ai/11-端到端实战.md"><strong>上线门槛</strong>：零件阶段「跑通就行」，上线阶段「每一步都得可回溯、可兜底、可止损」——这是完全不同的标准。</li></ol><p data-src-line="17" data-src-file="ai/11-端到端实战.md"><strong>这一篇的价值，就是带你走一遍这些衔接和权衡，让你对整个系列有一个「串起来」的通透感。</strong></p><blockquote data-src-line="19" data-src-file="ai/11-端到端实战.md"><p data-src-line="19" data-src-file="ai/11-端到端实战.md">打个比方：前面学了怎么选螺丝、怎么拧扳手，现在要真正组装一台机器，并确认它能安全运转。学到的每一个零件，都要在这里「上机验证」。</p></blockquote><hr><h2 id="_2-选一个能串起全部知识点的场景" tabindex="-1" data-src-line="23" data-src-file="ai/11-端到端实战.md">2. 选一个能串起全部知识点的场景 <a class="header-anchor" href="#_2-选一个能串起全部知识点的场景" aria-label="Permalink to &quot;2. 选一个能串起全部知识点的场景&quot;">​</a></h2><h3 id="_2-1-场景-企业内部的「智能知识问答-agent」" tabindex="-1" data-src-line="25" data-src-file="ai/11-端到端实战.md">2.1 场景：企业内部的「智能知识问答 Agent」 <a class="header-anchor" href="#_2-1-场景-企业内部的「智能知识问答-agent」" aria-label="Permalink to &quot;2.1 场景：企业内部的「智能知识问答 Agent」&quot;">​</a></h3><p data-src-line="27" data-src-file="ai/11-端到端实战.md">我们选一个<strong>能串起最多知识点</strong>的场景：<strong>企业内部知识库问答</strong>。</p><p data-src-line="29" data-src-file="ai/11-端到端实战.md">选它的理由：一个看似简单的问题「帮我查一下公司最新的报销政策」，背后要调动的东西几乎覆盖全篇——检索（03）、工具调用（04）、记忆（08）、评估（09）、护栏（10）。<strong>一个场景串起五篇，性价比最高。</strong></p><h3 id="_2-2-架构选型-用-07-的决策" tabindex="-1" data-src-line="31" data-src-file="ai/11-端到端实战.md">2.2 架构选型（用 07 的决策） <a class="header-anchor" href="#_2-2-架构选型-用-07-的决策" aria-label="Permalink to &quot;2.2 架构选型（用 07 的决策）&quot;">​</a></h3><p data-src-line="33" data-src-file="ai/11-端到端实战.md">这是「整合」的第一个权衡点。先看这个任务的特征：</p><ul data-src-line="35" data-src-file="ai/11-端到端实战.md"><li data-src-line="35" data-src-file="ai/11-端到端实战.md"><strong>步骤相对明确</strong>（查 → 组织 → 答）；</li><li data-src-line="36" data-src-file="ai/11-端到端实战.md"><strong>不需要多角色并行协作</strong>（就是「问 → 查 → 答」一条线）。</li></ul><p data-src-line="38" data-src-file="ai/11-端到端实战.md">所以结论很清晰：<strong>不上 Multi-Agent</strong>（那是过度设计），而是用 <strong>单 Agent（ReAct）＋ 一个 RAG 检索工具</strong>，足够且可控。</p><p data-src-line="40" data-src-file="ai/11-端到端实战.md"><strong>记住 07 的口诀：能用个体户，就别开公司。</strong> 整合的第一课，就是「克制」——不是零件越多越高级，而是「刚好够用」最专业。</p><hr><h2 id="_3-一步步搭出来" tabindex="-1" data-src-line="44" data-src-file="ai/11-端到端实战.md">3. 一步步搭出来 <a class="header-anchor" href="#_3-一步步搭出来" aria-label="Permalink to &quot;3. 一步步搭出来&quot;">​</a></h2><p data-src-line="46" data-src-file="ai/11-端到端实战.md">下面六步，每一步都对应前文的一个或几个零件，我会明确标出引用的篇章和「为什么这一步只做这些」。</p><h3 id="_3-1-第-1-步-定需求与边界-10-的前置" tabindex="-1" data-src-line="48" data-src-file="ai/11-端到端实战.md">3.1 第 1 步：定需求与边界（10 的前置） <a class="header-anchor" href="#_3-1-第-1-步-定需求与边界-10-的前置" aria-label="Permalink to &quot;3.1 第 1 步：定需求与边界（10 的前置）&quot;">​</a></h3><p data-src-line="50" data-src-file="ai/11-端到端实战.md">先把「它到底要干什么」钉死，越窄越好：</p><ul data-src-line="52" data-src-file="ai/11-端到端实战.md"><li data-src-line="52" data-src-file="ai/11-端到端实战.md"><strong>只做</strong>：根据内部知识库回答员工问题，并给出引用来源。</li><li data-src-line="53" data-src-file="ai/11-端到端实战.md"><strong>不做</strong>：不答知识库之外的事（避免它瞎编）；不执行任何写操作。</li></ul><p data-src-line="55" data-src-file="ai/11-端到端实战.md"><strong>这个「只做 / 不做」的清单，就是后面「权限最小化」的依据。</strong> 别忘了 10 篇的重要原则：<strong>安全不是事后补的，是需求阶段就定死的。</strong> 现在把边界划清楚，后面的护栏就是水到渠成，而不是亡羊补牢。</p><h3 id="_3-2-第-2-步-搭骨架-03-04" tabindex="-1" data-src-line="57" data-src-file="ai/11-端到端实战.md">3.2 第 2 步：搭骨架（03 + 04） <a class="header-anchor" href="#_3-2-第-2-步-搭骨架-03-04" aria-label="Permalink to &quot;3.2 第 2 步：搭骨架（03 + 04）&quot;">​</a></h3><p data-src-line="59" data-src-file="ai/11-端到端实战.md">先做最小闭环：一条「问题 → 检索 → 回答」的通路。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 最小可用 Agent：只给一个只读检索工具（权限最小化）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [检索知识库]                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只读，无写/删除</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">agent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ReAct(模型, tools)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 单 Agent 循环（04 篇）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">回答 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent.run(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;公司最新的报销政策是什么？&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p data-src-line="68" data-src-file="ai/11-端到端实战.md">这一步只验证「能查、能答」，不追求完美。<strong>关键决策：只给一个「检索」工具，且是只读的。</strong> 这既是 03 篇（RAG 检索）的落地，也是 10 篇（权限最小化）的第一道闸。</p><h3 id="_3-3-第-3-步-接入持久化-可观测-07-09" tabindex="-1" data-src-line="70" data-src-file="ai/11-端到端实战.md">3.3 第 3 步：接入持久化 + 可观测（07 + 09） <a class="header-anchor" href="#_3-3-第-3-步-接入持久化-可观测-07-09" aria-label="Permalink to &quot;3.3 第 3 步：接入持久化 + 可观测（07 + 09）&quot;">​</a></h3><ul data-src-line="72" data-src-file="ai/11-端到端实战.md"><li data-src-line="72" data-src-file="ai/11-端到端实战.md">给「检索并生成回答」的过程接<strong>检查点（checkpoint）</strong>，让它能断点续跑、能追踪（07 篇）；</li><li data-src-line="73" data-src-file="ai/11-端到端实战.md">接 <strong>Trace</strong>，每一次运行都留下轨迹（09 篇）。</li></ul><p data-src-line="75" data-src-file="ai/11-端到端实战.md"><strong>为什么这里不上「人工确认」？</strong> 因为这个 Agent <strong>只有只读、无副作用</strong>——它不会改数据、不会花钱，所以<strong>不需要人工把关</strong>。安全靠「根本不给写权限」就实现了（10 篇的权限最小化），而不是靠「关键动作前设关卡」。</p><p data-src-line="77" data-src-file="ai/11-端到端实战.md">这里体现一个重要的判断力：<strong>Human-in-the-loop 不是每个 Agent 都要的，只在「有不可逆副作用」时才需要。</strong> 一个只读的问答 Agent，硬加人工确认反而是画蛇添足。护栏的「剂量」，要根据「破坏能力」来配。</p><h3 id="_3-4-第-4-步-加记忆-08" tabindex="-1" data-src-line="79" data-src-file="ai/11-端到端实战.md">3.4 第 4 步：加记忆（08） <a class="header-anchor" href="#_3-4-第-4-步-加记忆-08" aria-label="Permalink to &quot;3.4 第 4 步：加记忆（08）&quot;">​</a></h3><p data-src-line="81" data-src-file="ai/11-端到端实战.md">给 Agent 加一层<strong>短期记忆</strong>：记住用户在<strong>这次会话里</strong>追问的上下文（「刚才说的那个政策，适用新员工吗？」）。</p><p data-src-line="83" data-src-file="ai/11-端到端实战.md">但<strong>暂时不上长期记忆</strong>——为什么？因为<strong>知识库本身就是「长期知识」</strong>：公司的政策、流程，都已经存在向量库里了。用户跨会话「上次我问过报销」这种个人长期偏好，在这个纯知识问答场景里价值不大，重复堆长期记忆反而冗余。</p><p data-src-line="85" data-src-file="ai/11-端到端实战.md"><strong>判断标准（这是整合的核心能力）：别为了「用上某个技术」而用它，只在「确实解决痛点」时才加。</strong> 08 篇讲的「记忆要提炼、召回、淘汰」，在这个场景里，知识库已经承担了「长期」的角色，Memory 只补「会话内短期」这一小块即可。</p><h3 id="_3-5-第-5-步-评估-可观测-09-上线前关键一步" tabindex="-1" data-src-line="87" data-src-file="ai/11-端到端实战.md">3.5 第 5 步：评估 + 可观测（09，上线前关键一步） <a class="header-anchor" href="#_3-5-第-5-步-评估-可观测-09-上线前关键一步" aria-label="Permalink to &quot;3.5 第 5 步：评估 + 可观测（09，上线前关键一步）&quot;">​</a></h3><p data-src-line="89" data-src-file="ai/11-端到端实战.md">这是<strong>上线前的关键一步</strong>，也是「demo」和「生产」的分水岭（呼应 07、09 篇的「分水岭」主题）：</p><ol data-src-line="91" data-src-file="ai/11-端到端实战.md"><li data-src-line="91" data-src-file="ai/11-端到端实战.md"><strong>建一个 50 条的小评测集</strong>：覆盖高频问题 + 边界问题（「问知识库外的问题」「问敏感数据」）。</li><li data-src-line="92" data-src-file="ai/11-端到端实战.md"><strong>接 Trace</strong>：每一次运行都留下轨迹，能回溯「它是怎么查到答案的」。</li><li data-src-line="93" data-src-file="ai/11-端到端实战.md"><strong>跑评测 + 看指标</strong>：成功率、引用准确率、平均步数、单次成本。</li></ol><p data-src-line="95" data-src-file="ai/11-端到端实战.md"><strong>这一关过了，才谈得上线。</strong> 具体到 RAG，尤其要盯「引用准确率」——因为一个「答对了但引用错了出处」的答案，在严肃场景里是<strong>不可信</strong>的（03 篇的引用回链）。</p><h3 id="_3-6-第-6-步-上线清单" tabindex="-1" data-src-line="97" data-src-file="ai/11-端到端实战.md">3.6 第 6 步：上线清单 <a class="header-anchor" href="#_3-6-第-6-步-上线清单" aria-label="Permalink to &quot;3.6 第 6 步：上线清单&quot;">​</a></h3><p data-src-line="99" data-src-file="ai/11-端到端实战.md">上线前逐条打勾，每一条都能回溯到前文的某个「命门」：</p><ul data-src-line="101" data-src-file="ai/11-端到端实战.md"><li data-src-line="101" data-src-file="ai/11-端到端实战.md">[ ] 检索工具是<strong>只读</strong>的，无任何写/删除权限（10 权限最小化）</li><li data-src-line="102" data-src-file="ai/11-端到端实战.md">[ ] 外部知识库内容按<strong>不可信数据</strong>对待，关键动作有白名单（10 防注入）</li><li data-src-line="103" data-src-file="ai/11-端到端实战.md">[ ] 接入了<strong>检查点 + Trace</strong>，能断点续跑、能回溯（09 可观测）</li><li data-src-line="104" data-src-file="ai/11-端到端实战.md">[ ] 有<strong>评测集</strong>，且上线前跑通了（09 评估）</li><li data-src-line="105" data-src-file="ai/11-端到端实战.md">[ ] 设了<strong>成本上限</strong>（防烧钱）+ <strong>失败兜底</strong>（查不到时明确说「查不到」，而非瞎编）</li></ul><p data-src-line="107" data-src-file="ai/11-端到端实战.md">最后一条「失败兜底」值得单独强调：<strong>RAG 最怕的就是「查不到却硬编」。</strong> 一定要让 Agent 在检索无果时，明确回答「抱歉，知识库里没有相关资料」，而不是让模型「自以为知道」地编一个——这既是 03 篇的「溯源」要求，也是最常见的生产事故源头。</p><hr><h2 id="_4-复盘对照表-把-01–10-的命门逐条打勾" tabindex="-1" data-src-line="111" data-src-file="ai/11-端到端实战.md">4. 复盘对照表：把 01–10 的命门逐条打勾 <a class="header-anchor" href="#_4-复盘对照表-把-01–10-的命门逐条打勾" aria-label="Permalink to &quot;4. 复盘对照表：把 01–10 的命门逐条打勾&quot;">​</a></h2><p data-src-line="113" data-src-file="ai/11-端到端实战.md">这张表，是整个系列的一份「索引」。它把每一篇的核心知识点，都映射到「在本例中怎么落地」，帮你验证「到底学会了没有」：</p><table tabindex="0"><thead data-src-line="115" data-src-file="ai/11-端到端实战.md"><tr data-src-line="115" data-src-file="ai/11-端到端实战.md"><th>篇</th><th>知识点</th><th>在本例中怎么落地</th></tr></thead><tbody data-src-line="117" data-src-file="ai/11-端到端实战.md"><tr data-src-line="117" data-src-file="ai/11-端到端实战.md"><td>02 提示词</td><td>清晰的 system 约束「只答知识库内的」</td><td>✅ 需求边界里写死</td></tr><tr data-src-line="118" data-src-file="ai/11-端到端实战.md"><td>03 RAG</td><td>检索 + 引用回链</td><td>✅ 检索工具 + 给来源</td></tr><tr data-src-line="119" data-src-file="ai/11-端到端实战.md"><td>04 FC/Agent</td><td>单 Agent 循环调工具</td><td>✅ ReAct 骨架</td></tr><tr data-src-line="120" data-src-file="ai/11-端到端实战.md"><td>05 框架</td><td>用 LangGraph 编排</td><td>✅ 节点/边/检查点</td></tr><tr data-src-line="121" data-src-file="ai/11-端到端实战.md"><td>06 MCP</td><td>工具能否生态复用来接入</td><td>🔶 检索工具可封装成 MCP Server 供其它 Agent 复用</td></tr><tr data-src-line="122" data-src-file="ai/11-端到端实战.md"><td>07 编排</td><td>单 Agent 够用，不上多 Agent</td><td>✅ 架构选型</td></tr><tr data-src-line="123" data-src-file="ai/11-端到端实战.md"><td>08 记忆</td><td>短期记忆够用，不上长期</td><td>✅ 克制</td></tr><tr data-src-line="124" data-src-file="ai/11-端到端实战.md"><td>09 评估</td><td>评测集 + Trace + 指标</td><td>✅ 上线门槛</td></tr><tr data-src-line="125" data-src-file="ai/11-端到端实战.md"><td>10 护栏</td><td>只读权限 + 防注入 + 成本上限</td><td>✅ 上线清单</td></tr></tbody></table><blockquote data-src-line="127" data-src-file="ai/11-端到端实战.md"><p data-src-line="127" data-src-file="ai/11-端到端实战.md">🔶 表示「可选优化」：当前不阻塞上线，但日后若想让这个检索能力被其它 Agent 复用，可把它封装成 MCP Server（呼应 06 篇「写一次、处处可用」）。</p></blockquote><p data-src-line="129" data-src-file="ai/11-端到端实战.md">这张表的意义，不只在于「本例」。<strong>你可以把它当成一个「checklist 模板」</strong>——以后你每搭一个 Agent，都可以拿这张表过一遍，问自己「这 10 个维度，我考虑全了吗」。你会发现，「漏掉某一篇的命门」，正是大多数 Agent 项目失败的常见原因。</p><hr><h2 id="_5-记住这一句" tabindex="-1" data-src-line="133" data-src-file="ai/11-端到端实战.md">5. 记住这一句 <a class="header-anchor" href="#_5-记住这一句" aria-label="Permalink to &quot;5. 记住这一句&quot;">​</a></h2><blockquote data-src-line="135" data-src-file="ai/11-端到端实战.md"><p data-src-line="135" data-src-file="ai/11-端到端实战.md"><strong>搭 Agent 不是堆零件，是「先跑通最小闭环 → 再按需加记忆/护栏 → 最后用评测集把关才上线」。每个零件只在「真的解决痛点」时才加，加得越多，越要记得它带来的新风险。</strong></p></blockquote><hr><p data-src-line="139" data-src-file="ai/11-端到端实战.md"><strong>全文结束。</strong> 从 01 到 11，你走完了一条完整路线：先建立「Agent 是什么」的心智模型，再逐层拼上「会对话、懂数据、会行动、会落地、会协作、长记性、可度量、守边界」，最后亲手组装出一台能上线的机器。</p><p data-src-line="141" data-src-file="ai/11-端到端实战.md">接下来，剩下的就是<strong>把每一篇读深，把每一个「命门」变成你能随时复述的红线</strong>——因为真正的功力，不在「知道这些概念」，而在「能在关键时刻想起并守住这些红线」。</p>`,58)])])}const m=t(d,[["render",e]]);export{p as __pageData,m as default};
